import csv
import io
import re
from typing import List, Dict, Any

def parse_csv(raw_csv: str):
    width = 9
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False
    )
    parsed = []
    try:
        for row in reader:
            parsed.append(row)
    except csv.Error:
        parsed = []
        for line in text.splitlines():
            try:
                parsed.append(next(csv.reader(
                    [line],
                    delimiter=",",
                    quotechar='"',
                    doublequote=True,
                    strict=False
                )))
            except Exception:
                parsed.append(line.split(","))

    def clean_cell(value):
        return value.lstrip("\ufeff") if isinstance(value, str) else str(value)

    def repair(row):
        row = [clean_cell(x) for x in row]
        if len(row) == width:
            return row
        if len(row) < width:
            return row + [""] * (width - len(row))

        url_index = None
        for i in range(6, len(row)):
            if re.match(r"(?i)^https?://", row[i].strip()):
                url_index = i
                break

        if url_index is not None:
            description = ",".join(row[6:url_index])
            comments = ",".join(row[url_index + 1:])
            return row[:6] + [description, row[url_index], comments]

        overflow = len(row) - width
        split_at = max(6, len(row) - 2)
        description = ",".join(row[6:split_at + overflow])
        tail = row[split_at + overflow:]
        result = row[:6] + [description] + tail
        if len(result) < width:
            result.extend([""] * (width - len(result)))
        return result[:width]

    date_pattern = re.compile(
        r"^\s*(?:\d{1,4}[/-]\d{1,2}[/-]\d{1,4}|\d{1,2}[/-]\d{1,2}[/-]\d{2,4})\s*$"
    )

    header_words = {
        "date", "time", "qty", "quantity", "productid", "product",
        "price", "producttype", "type", "productdescription",
        "description", "url", "link", "comments", "comment"
    }

    def header_score(row):
        score = 0
        for cell in row:
            token = re.sub(r"[^a-z0-9]+", "", cell.lower())
            if token in header_words:
                score += 1
        return score

    candidates = []
    for index, row in enumerate(parsed):
        if not row or not any(str(x).strip() for x in row):
            continue
        score = header_score(row)
        if score:
            candidates.append((score, index))

    header_index = None
    if candidates:
        candidates.sort(key=lambda item: (-item[0], item[1]))
        header_index = candidates[0][1]

    if header_index is not None:
        columns = repair(parsed[header_index])
    else:
        columns = [
            "column1", "column2", "column3", "column4", "column5",
            "column6", "column7", "column8", "column9"
        ]

    header_indices = set(index for _, index in candidates)
    rows = []

    for index, raw_row in enumerate(parsed):
        if not raw_row or not any(str(x).strip() for x in raw_row):
            continue
        if index in header_indices:
            continue

        first = str(raw_row[0]).strip() if raw_row else ""
        looks_like_data = bool(date_pattern.match(first))

        if header_index is not None and index < header_index and not looks_like_data:
            continue

        if header_index is None and not looks_like_data:
            if len(raw_row) <= 1:
                continue
            if header_score(raw_row) == 0:
                continue

        row = repair(raw_row)
        if any(cell != "" for cell in row):
            rows.append(row)

    return {"columns": columns, "rows": rows}
